void muisc_setup_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_muisc_setup_obj_t * p_screen_param;
    lv_obj_t *      list = get_muisc_setup_list_obj(ui_Screen);
    uint32_t        child_cnt = lv_obj_get_child_cnt(list);
    uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;
    lv_obj_t *      label;

    p_screen_param      = (ui_screen_muisc_setup_obj_t *) lv_obj_get_user_data(ui_Screen);

    __inf("muisc_setup_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);

    switch (key)
    {
        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,1);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,1);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

        case LV_KEY_ENTER:
        case APP_KEY_VALUE_TOP_LEFT:
            {
                switch (child_id)
                {
                    case ENUM_MUSIC_SETUP_SINGLE:
                    case ENUM_MUSIC_SETUP_ORDER:
                    case ENUM_MUSIC_SETUP_DISORDER:
                        //case ENUM_MUSIC_SETUP_LOOP:
                        {
                            lv_obj_t *      ui_icon1;

                            if (p_screen_param->play_mode == child_id)
                                break;

                            get_focus_obj       = lv_obj_get_child(list,child_id);
                            ui_icon1            = lv_obj_get_child(get_focus_obj,0);
                            lv_img_set_src(ui_icon1,ui_imgset_select[1]);
                            lv_obj_set_user_data(ui_icon1,(void *) 1);

                            get_focus_obj       = lv_obj_get_child(list,p_screen_param->play_mode);
                            ui_icon1            = lv_obj_get_child(get_focus_obj,0);
                            lv_img_set_src(ui_icon1,ui_imgset_select[0]);
                            lv_obj_set_user_data(ui_icon1,0);

                            p_screen_param->play_mode = child_id;
                            app_musicplayer_set_playmode_action(p_screen_param->play_mode);

                            alv_am_win_exit_action(NULL,"music_option",NULL);
                            alv_am_win_exit_current(NULL);
                            }
                        break;
                    }

                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);

                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}







